/* ---------- Course card on the Learning list ---------- */
function LearningCard({ course, progress, onOpen }) {
  const status = progress.completed >= course.lessons.length ? 'completed' : progress.started ? 'in-progress' : 'not-started';
  const label = status === 'completed' ? 'Completed' : status === 'in-progress' ? `${progress.percent}% complete` : 'Not started';
  const btnLabel = status === 'completed' ? 'Review' : status === 'in-progress' ? 'Resume' : 'Start course';
  return (
    <div className="learn-card" onClick={onOpen}>
      <div className="learn-thumb" style={{ background: course.gradient }} />
      <div className="learn-card-body">
        <span className="learn-topic-pill">{course.topic}</span>
        <h3>{course.title}</h3>
        <p>{course.desc}</p>
        <div className="learn-card-meta">
          <span><Icon name="clock" size={12} color="#9CA3AF" /> {course.duration}</span>
          {course.lessons.length > 1 && <span><Icon name="book" size={12} color="#9CA3AF" /> {course.lessons.length} lessons</span>}
        </div>
        <div className="learn-card-progress">
          <div>
            <div className="txt">{label}</div>
            {status !== 'not-started' && <div className="bar"><span style={{ width: `${progress.percent}%` }} /></div>}
          </div>
          <button className="learn-card-btn" onClick={(e) => { e.stopPropagation(); onOpen(); }}>{btnLabel}</button>
        </div>
      </div>
    </div>
  );
}

/* ---------- Learning list page ---------- */
function LearningList({ progress, filter, setFilter, sort, setSort, sortMenuOpen, setSortMenuOpen, onOpenCourse }) {
  const featuredId = COURSES.find((c) => {
    const p = progress[c.id];
    return p && p.started && p.completed < c.lessons.length;
  });
  const featured = featuredId;

  let list = filter === 'All topics' ? COURSES : COURSES.filter((c) => c.topic === filter);
  const sorted = [...list].sort((a, b) => {
    if (sort === 'Progress') return (progress[b.id]?.percent || 0) - (progress[a.id]?.percent || 0);
    if (sort === 'Duration') return durationToMinutes(a.duration) - durationToMinutes(b.duration);
    if (sort === 'A–Z') return a.title.localeCompare(b.title);
    if (sort === 'Newest') return b.updated.localeCompare(a.updated);
    return 0;
  });

  return (
    <>
      <div className="dash-page-head">
        <h1>Learning</h1>
        <p>Build your understanding of clean and renewable energy at your own pace.</p>
      </div>

      {featured && (
        <div className="learn-continue-banner">
          <div>
            <div className="eyebrow">CONTINUE LEARNING</div>
            <h3>{featured.title}</h3>
            <div className="sub">Lesson {progress[featured.id].completed + 1} of {featured.lessons.length} · {featured.lessons[progress[featured.id].completed]}</div>
            <div className="bar"><span style={{ width: `${progress[featured.id].percent}%` }} /></div>
            <div className="pct">{progress[featured.id].percent}% complete</div>
          </div>
          <button className="learn-resume-btn" onClick={() => onOpenCourse(featured.id)}>Resume <ArrowRight size={14} color="#5B21B6" /></button>
        </div>
      )}

      <div className="learn-filters">
        <div className="learn-pill-row">
          {LEARNING_TOPICS.map((t) => (
            <button key={t} className={`learn-fpill${filter === t ? ' active' : ''}`} onClick={() => setFilter(t)}>{t}</button>
          ))}
        </div>
        <div className="learn-sort">
          <button className="learn-sort-btn" onClick={() => setSortMenuOpen((o) => !o)}>{sort} <Icon name="chevronDown" size={14} color="#9CA3AF" /></button>
          {sortMenuOpen && (
            <div className="learn-sort-menu">
              {['Progress', 'Newest', 'Duration', 'A–Z'].map((o) => (
                <div key={o} className={`learn-sort-option${sort === o ? ' active' : ''}`} onClick={() => { setSort(o); setSortMenuOpen(false); }}>{o}</div>
              ))}
            </div>
          )}
        </div>
      </div>

      <div className="learn-grid">
        {sorted.length === 0 && <div className="learn-empty">No courses in this topic yet.</div>}
        {sorted.map((c) => (
          <LearningCard key={c.id} course={c} progress={progress[c.id] || { started: false, completed: 0, percent: 0 }} onOpen={() => onOpenCourse(c.id)} />
        ))}
      </div>
    </>
  );
}

/* ---------- Shared real video player: play/pause, seek, volume, fullscreen ---------- */
let _demoVideoUrl = null;
function getDemoVideoUrl(forceDataUri) {
  if (VIDEO_URL_OVERRIDE && !forceDataUri) return VIDEO_URL_OVERRIDE;
  if (forceDataUri) return 'data:video/mp4;base64,' + DEMO_VIDEO_B64;
  if (_demoVideoUrl) return _demoVideoUrl;
  try {
    const bin = atob(DEMO_VIDEO_B64);
    const bytes = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
    _demoVideoUrl = URL.createObjectURL(new Blob([bytes], { type: 'video/mp4' }));
  } catch (e) {
    _demoVideoUrl = 'data:video/mp4;base64,' + DEMO_VIDEO_B64;
  }
  return _demoVideoUrl;
}
function fmtClock(sec) {
  if (!isFinite(sec) || sec < 0) sec = 0;
  const m = Math.floor(sec / 60); const ss = String(Math.floor(sec % 60)).padStart(2, '0');
  return `${m}:${ss}`;
}

/* Still frame from the real video, used as a thumbnail behind play buttons */
function VideoFrame({ style }) {
  const [src, setSrc] = useState(() => getDemoVideoUrl());
  return (
    <video
      onError={() => setSrc(getDemoVideoUrl(true))}
      src={src + '#t=0.5'} muted playsInline preload="metadata" aria-hidden="true" tabIndex={-1}
      style={{ position: 'absolute', inset: 0, width: '100%', height: '100%', objectFit: 'cover', pointerEvents: 'none', ...style }}
    />
  );
}

const VideoPlayer = forwardRef(function VideoPlayer({ startFraction = 0, completed = false, pausedOverlay = null, onFirstPlay, onTime, onEnded }, ref) {
  const wrapRef = useRef(null);
  const vidRef = useRef(null);
  const trackRef = useRef(null);
  const dragging = useRef(false);
  const started = useRef(false);
  const [playing, setPlaying] = useState(false);
  const [cur, setCur] = useState(0);
  const [dur, setDur] = useState(0);
  const [volume, setVolume] = useState(70);
  const [muted, setMuted] = useState(false);
  const [showVol, setShowVol] = useState(false);
  const [isFs, setIsFs] = useState(false);
  const [scrubbing, setScrubbing] = useState(false);
  const [src, setSrc] = useState(() => getDemoVideoUrl());

  const play = () => { const v = vidRef.current; if (v) { const r = v.play(); if (r && r.catch) r.catch(() => {}); } };
  const pause = () => { const v = vidRef.current; if (v) v.pause(); };
  const toggle = () => { const v = vidRef.current; if (!v) return; if (v.paused || v.ended) play(); else pause(); };
  const seekFraction = (f, andPlay) => {
    const v = vidRef.current; if (!v || !v.duration) return;
    v.currentTime = Math.max(0, Math.min(1, f)) * v.duration;
    setCur(v.currentTime);
    if (andPlay) play();
  };
  useImperativeHandle(ref, () => ({ play, pause, seekFraction }));

  useEffect(() => { const v = vidRef.current; if (v) { v.volume = volume / 100; v.muted = muted; } }, [volume, muted]);
  useEffect(() => {
    const onFs = () => setIsFs(document.fullscreenElement === wrapRef.current);
    document.addEventListener('fullscreenchange', onFs);
    return () => document.removeEventListener('fullscreenchange', onFs);
  }, []);

  function toggleFullscreen() {
    const el = wrapRef.current; const v = vidRef.current;
    if (document.fullscreenElement) { document.exitFullscreen && document.exitFullscreen().catch(() => {}); return; }
    if (el && el.requestFullscreen) el.requestFullscreen().catch(() => {});
    else if (v && v.webkitEnterFullscreen) v.webkitEnterFullscreen();   // iOS Safari
  }
  function seekFromPointer(e) {
    const r = trackRef.current.getBoundingClientRect();
    seekFraction((e.clientX - r.left) / r.width);
  }
  function onKey(e) {
    if (e.target && e.target.tagName === 'INPUT') return;
    const v = vidRef.current; if (!v) return;
    if (e.key === ' ' || e.key === 'k') { e.preventDefault(); toggle(); }
    else if (e.key === 'ArrowRight') { e.preventDefault(); v.currentTime = Math.min(v.duration || 0, v.currentTime + 5); }
    else if (e.key === 'ArrowLeft') { e.preventDefault(); v.currentTime = Math.max(0, v.currentTime - 5); }
    else if (e.key === 'm') setMuted((m) => !m);
    else if (e.key === 'f') toggleFullscreen();
  }

  const pct = dur ? (cur / dur) * 100 : 0;
  const PlayTri = (<Icon name="play" size={28} color="#6700A6" />);

  return (
    <div className={`video-player vp2${isFs ? ' fs' : ''}${scrubbing ? ' scrubbing' : ''}`} ref={wrapRef} tabIndex={0} onKeyDown={onKey}>
      <div className="video-visual" onClick={toggle} onDoubleClick={toggleFullscreen}>
        <video
          ref={vidRef} className="vp2-video" src={src} playsInline preload="auto"
          onError={() => { const fb = getDemoVideoUrl(true); if (src !== fb) setSrc(fb); }}
          onLoadedMetadata={(e) => {
            const v = e.currentTarget; setDur(v.duration);
            v.currentTime = startFraction > 0 ? startFraction * v.duration : 0.05;   // also paints the first frame
          }}
          onPlay={() => { setPlaying(true); if (!started.current) { started.current = true; onFirstPlay && onFirstPlay(); } }}
          onPause={() => setPlaying(false)}
          onTimeUpdate={(e) => { const v = e.currentTarget; setCur(v.currentTime); onTime && onTime(v.currentTime, v.duration); }}
          onEnded={() => { setPlaying(false); onEnded && onEnded(); }}
        />
        {!playing && pausedOverlay && <div className="vp2-overlay">{pausedOverlay}</div>}
        {!playing && !pausedOverlay && (
          <button className="video-play-btn" onClick={(e) => { e.stopPropagation(); play(); }} aria-label="Play">{PlayTri}</button>
        )}
      </div>
      <div className="video-controls" onClick={(e) => e.stopPropagation()}>
        <div
          className="vc-track" ref={trackRef}
          onPointerDown={(e) => { dragging.current = true; setScrubbing(true); e.currentTarget.setPointerCapture(e.pointerId); seekFromPointer(e); }}
          onPointerMove={(e) => { if (dragging.current) seekFromPointer(e); }}
          onPointerUp={() => { dragging.current = false; setScrubbing(false); }}
          onPointerCancel={() => { dragging.current = false; setScrubbing(false); }}
        >
          <div className="vc-fill" style={{ width: `${pct}%`, background: completed ? '#A78BFA' : undefined }} />
        </div>
        <div className="vc-row">
          <button className="vc-btn" onClick={toggle} aria-label={playing ? 'Pause' : 'Play'}>
            {playing ? <Icon name="pause" size={18} color="#fff" /> : <Icon name="play" size={18} color="#fff" />}
          </button>
          <span className="vc-time">{fmtClock(cur)} / {fmtClock(dur)}</span>
          <span className="vc-spacer" />
          <div className="vc-volume-wrap" onMouseEnter={() => setShowVol(true)} onMouseLeave={() => setShowVol(false)}>
            {showVol && (
              <input type="range" min="0" max="100" value={muted ? 0 : volume} className="vc-volume-slider" aria-label="Volume"
                onChange={(e) => { setVolume(Number(e.target.value)); setMuted(false); }} />
            )}
            <button className="vc-btn" onClick={() => setMuted((m) => !m)} aria-label={muted ? 'Unmute' : 'Mute'}>
              {muted || volume === 0 ? <Icon name="volumeMute" size={18} color="#fff" /> : <Icon name="volume" size={18} color="#fff" />}
            </button>
          </div>
          <button className="vc-btn" onClick={toggleFullscreen} aria-label={isFs ? 'Exit fullscreen' : 'Fullscreen'} title={isFs ? 'Exit fullscreen' : 'Fullscreen'}><Icon name={isFs ? 'collapse' : 'expand'} size={18} color="#fff" /></button>
        </div>
      </div>
    </div>
  );
});

/* ---------- Course detail page ---------- */
function CourseDetail({ course, progress, status, onStart, onContinue, onStartAgain, onSave, onOpenReview, onBack, related, onOpenRelated }) {
  const playerRef = useRef(null);
  const completed = status === 'completed';

  return (
    <>
      <button className="learn-back" onClick={onBack}><ArrowLeft size={15} color="#5B21B6" /> Back to Learning</button>

      <div className="course-layout">
        <div className="course-main">
          <VideoPlayer
            key={course.id}
            ref={playerRef}
            completed={completed}
            startFraction={status === 'in-progress' || status === 'completed' ? 45 / 2530 : 0}
            pausedOverlay={completed ? (
              <div className="video-complete-badge">
                <span className="ico"><Check size={22} color="#fff" strokeWidth={3} /></span>
                <div className="t">Course completed</div>
                <div className="s">All {course.lessons.length} lessons finished</div>
              </div>
            ) : null}
          />

          {completed && (
            <div className="course-complete-banner">
              <span className="ico"><Check size={15} color="#fff" strokeWidth={3} /></span>
              <div>
                <div className="t">You completed this course</div>
                <div className="s">Finished today · {course.duration} total learning time</div>
              </div>
            </div>
          )}

          <div className="course-info-card">
            <span className="topic-pill">{course.topic}</span>
            <h1>{course.title}</h1>
            <div className="meta">Updated {course.updated} · {course.duration} · {course.lessons.length} lesson{course.lessons.length > 1 ? 's' : ''}</div>
            <p>{course.about}</p>
            <h4>{course.whyTitle}</h4>
            <p>{course.why}</p>
            <div className="takeaways-box">
              <div className="tk-title">Key takeaways</div>
              <ul>{course.takeaways.map((t, i) => (<li key={i}>{t}</li>))}</ul>
            </div>
            <h4>Getting started</h4>
            <p>{course.gettingStarted}</p>
          </div>
        </div>

        <div className="course-sidebar">
          <div className="lesson-card">
            <h3>{course.title}</h3>
            <div className="lesson-progress-row">
              <div className="bar"><span style={{ width: `${progress.percent}%` }} /></div>
              <span className="pct">{progress.percent}%</span>
            </div>
            <div className="lesson-count-text">{progress.completed} of {course.lessons.length} lesson{course.lessons.length > 1 ? 's' : ''} complete</div>
            <ul className="lesson-list">
              {course.lessons.map((l, i) => {
                const isDone = i < progress.completed;
                const isCurrent = i === progress.completed && status === 'in-progress';
                return (
                  <li key={i} className={`${isDone ? 'done' : ''} ${isCurrent ? 'current' : ''}`}>
                    <span className="num">{isDone ? <Check size={11} color="#fff" strokeWidth={3} /> : i + 1}</span>
                    {l}
                  </li>
                );
              })}
            </ul>
          </div>

          <div className="related-card">
            <h4>Related learning</h4>
            {related.map((r) => (
              <button key={r.id} className="related-item" onClick={() => onOpenRelated(r.id)}>
                <div className="rt">{r.title}</div>
                <div className="rs">{r.topic} · {r.duration}</div>
              </button>
            ))}
          </div>
        </div>
      </div>

      <div className="course-action-bar">
        {status === 'not-started' && <button className="btn-primary-lg" onClick={() => { playerRef.current && playerRef.current.play(); onStart(); }}>Start course</button>}
        {status === 'in-progress' && <button className="btn-primary-lg" onClick={() => { playerRef.current && playerRef.current.play(); onContinue(); }}>Continue</button>}
        {status === 'completed' && (
          <>
            <button className="btn-outline-lg" onClick={onStartAgain}>Start Again</button>
            <button className="btn-outline-lg" onClick={onSave}>Save</button>
            <button className="btn-primary-lg" onClick={onOpenReview}>Review</button>
          </>
        )}
      </div>
    </>
  );
}

/* ---------- Review modal ---------- */
function ReviewModal({ course, onClose }) {
  return (
    <div className="modal-overlay" onClick={(e) => { if (e.target === e.currentTarget) onClose(); }}>
      <div className="modal-card">
        <button className="modal-close-x" onClick={onClose}><X size={14} color="#fff" strokeWidth={2.4} /></button>
        <h2>Course review</h2>
        <p className="sub">{course.title}</p>
        <div className="review-modal-list">
          {course.lessons.map((l, i) => (
            <div className="review-modal-item" key={i}>
              <span className="ico"><Check size={11} color="#fff" strokeWidth={3} /></span>
              {l} — Completed
            </div>
          ))}
        </div>
        <p style={{ fontSize: '12.6px', color: '#4B5563', marginBottom: 20 }}>
          {course.lessons.length} of {course.lessons.length} lessons completed · {course.duration} total learning time
        </p>
        <PrimaryButton enabled onClick={onClose}>Done</PrimaryButton>
      </div>
    </div>
  );
}

