function findEvent(id) { return EVENTS.find((e) => e.id === id); }
function findRecording(id) { return RECORDINGS.find((r) => r.id === id); }

function fmtTime(s) { const m = Math.floor(s / 60); const ss = String(Math.floor(s % 60)).padStart(2, '0'); return `${m}:${ss}`; }

function downloadIcs(event) {
  try {
    const start = new Date(event.startISO);
    const end = new Date(start.getTime() + (event.durationMinutes || 60) * 60000);
    const fmt = (d) => d.toISOString().replace(/[-:]/g, '').split('.')[0];
    const ics = [
      'BEGIN:VCALENDAR', 'VERSION:2.0', 'BEGIN:VEVENT',
      `SUMMARY:${event.title}`, `DTSTART:${fmt(start)}Z`, `DTEND:${fmt(end)}Z`,
      `LOCATION:${event.location}`, `DESCRIPTION:${(event.about || '').replace(/\n/g, ' ')}`,
      'END:VEVENT', 'END:VCALENDAR',
    ].join('\r\n');
    const blob = new Blob([ics], { type: 'text/calendar' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url; a.download = `${event.id}.ics`;
    document.body.appendChild(a); a.click(); document.body.removeChild(a);
    URL.revokeObjectURL(url);
  } catch (e) { /* ignore in sandboxed preview */ }
}

