/* ---------- Event detail page ---------- */
/* Host profile — opened from "View profile" on the event details page.
   Contractor hosts open their full contractor profile; other hosts get this profile card. */
const HOST_KEYS = { 'Helios Solar Solutions': 'helios', 'Ngozi Adeleke': 'ngozi', 'GridWorks Energy': 'gridworks' };
const hostKeyFor = (name) => HOST_KEYS[name] || name.toLowerCase().replace(/[^a-z0-9]+/g, '-');
function HostProfileModal({ host, currentEventId, following, onToggleFollow, onOpenEvent, onClose }) {
  const [box, setBox] = useState({ left: 0, top: 0 });
  useLayoutEffect(() => {
    const measure = () => {
      const sb = document.querySelector('.dash-sidebar'), tb = document.querySelector('.dash-topbar');
      setBox({ left: sb ? Math.max(0, Math.round(sb.getBoundingClientRect().right)) : 0, top: tb ? Math.round(tb.getBoundingClientRect().bottom) : 0 });
    };
    measure();
    window.addEventListener('resize', measure);
    return () => window.removeEventListener('resize', measure);
  }, []);
  useEffect(() => {
    const onKey = (e) => { if (e.key === 'Escape') onClose(); };
    document.addEventListener('keydown', onKey);
    return () => document.removeEventListener('keydown', onKey);
  }, [onClose]);

  const hostEvents = EVENTS.filter((e) => e.host.name === host.name);
  const recs = RECORDINGS.filter((r) => r.hostName === host.name);
  const stats = [[hostEvents.length, 'Upcoming events'], [recs.length, 'Recordings']];

  return (
    <div className="lb-ov ct-ov" style={{ left: box.left, top: box.top }} onMouseDown={(e) => e.target === e.currentTarget && onClose()}>
      <div className="lb-modal ct hp" role="dialog" aria-modal="true" aria-labelledby="hp-title">
        <button className="lb-close" onClick={onClose} aria-label="Close"><Icon name="close" size={17} strokeWidth={3} /></button>
        <div className="lb-head hp-head">
          <div className="hp-ava" style={{ background: host.color }}>{host.initial}</div>
          <div className="hp-id">
            <h2 id="hp-title">{host.name}{host.verified && <span className="ev-verified-pill"><Check size={10} color="#0F8A5F" strokeWidth={2.4} /> Verified</span>}</h2>
            <p>{host.role}</p>
          </div>
        </div>
        <div className="lb-body">
          <h4 className="hp-h">About</h4>
          <p className="hp-bio">{host.bio}</p>
          <div className="hp-stats">
            {stats.map(([n, l]) => (<div key={l}><b>{n}</b><span>{l}</span></div>))}
          </div>
          <h4 className="hp-h">Upcoming events by {host.name}</h4>
          {hostEvents.length === 0 ? (
            <p className="hp-empty">No upcoming events from this host right now.</p>
          ) : hostEvents.map((e) => {
            const here = e.id === currentEventId;
            return (
              <button key={e.id} type="button" className={`hp-event${here ? ' here' : ''}`} disabled={here} onClick={() => onOpenEvent(e.id)}>
                <span className="hp-date"><b>{e.shortDate.day}</b>{e.shortDate.month}</span>
                <span className="hp-einfo"><span className="t">{e.title}</span><span className="s">{e.day} · {e.time} · {e.isOnline ? 'Online' : e.location}</span></span>
                {here ? <span className="hp-viewing">Viewing</span> : <ArrowRight size={14} color="#6700A6" />}
              </button>
            );
          })}
        </div>
        <div className="lb-foot">
          <button className="lb-btn lb-cancel" onClick={onClose}>Close</button>
          <button className={`lb-btn lb-submit hp-follow${following ? ' following' : ''}`} onClick={onToggleFollow} aria-pressed={!!following}>{following ? 'Following' : 'Follow host'}</button>
        </div>
      </div>
    </div>
  );
}

