/* ---------- Recording player ---------- */
const UPNEXT_GRADIENTS = { 'webinar': 'linear-gradient(135deg,#6700A6,#9B4DD6)', 'workshop': 'linear-gradient(135deg,#0E7C86,#2AAFBC)', 'office-hours': 'linear-gradient(135deg,#B26A00,#E39B38)', 'community': 'linear-gradient(135deg,#2457C5,#4F86E8)' };
const UPNEXT_LABEL = { 'community': 'Meetup' };

function RecordingPlayer({ recording, watched, liked, saved, onBack, onLike, onSave, onShare, onDownloadResource, onOpenUpNext, onFirstPlay }) {
  const playerRef = useRef(null);
  const [frac, setFrac] = useState(0);
  useEffect(() => { setFrac(0); }, [recording.id]);

  // Chapters are on the recording's own timeline; map them proportionally onto the real clip.
  function jumpToChapter(t) { playerRef.current && playerRef.current.seekFraction(t / recording.totalSeconds, true); }
  const currentChapterIdx = recording.chapters.reduce((acc, c, i) => (c.t / recording.totalSeconds <= frac + 0.0005 ? i : acc), 0);

  const upNext = (() => {
    const seen = new Set([recording.title]);
    return RECORDINGS.filter((r) => { if (r.id === recording.id || seen.has(r.title)) return false; seen.add(r.title); return true; }).slice(0, 3);
  })();

  return (
    <div className="ev-page ev-detail ev-rp">
      <button className="learn-back" onClick={onBack}><ArrowLeft size={12} color="#6700A6" /> Back to Past Events</button>
      <div className="course-layout">
        <div className="course-main">
          <VideoPlayer key={recording.id} ref={playerRef} onFirstPlay={onFirstPlay} onTime={(t, d) => setFrac(d ? t / d : 0)} />

          <div className="rp-below">
            <div className="rp-badges">
              {typePill(recording.typeKey, recording.type)}
              {watched && <span className="ev-watched-pill"><Check size={10} color="#0F8A5F" strokeWidth={2.4} /> Watched</span>}
            </div>
            <h1 className="rp-title">{recording.title}</h1>
            <div className="rp-host">
              <div className="h-ava" style={{ background: '#6700A6' }}>{recording.hostInitial}</div>
              <span className="h-name">{recording.hostName}</span>
              {recording.hostVerified && <span className="ev-verified-pill"><Check size={10} color="#0F8A5F" strokeWidth={2.4} /> Verified</span>}
              <span className="h-date">{recording.date.replace(/^Recorded /, 'Recorded ')}</span>
            </div>
            <div className="rp-action-row">
              <button className={`rp-action-btn${liked ? ' active' : ''}`} onClick={onLike}><Icon name={liked ? 'heartFilled' : 'heart'} size={16} color={liked ? '#DC2626' : '#6B6B76'} /> Like</button>
              <button className={`rp-action-btn${saved ? ' active' : ''}`} onClick={onSave}><Icon name={saved ? 'bookmarkFilled' : 'bookmark'} size={16} color={saved ? '#6700A6' : '#6B6B76'} /> {saved ? 'Saved' : 'Save'}</button>
              <button className="rp-action-btn" onClick={onShare}><Icon name="share" size={16} color="#6B6B76" /> Share</button>
              <button className="rp-action-btn" onClick={() => onDownloadResource('all recording resources')}><Icon name="download" size={16} color="#6B6B76" /> Download resources</button>
            </div>
          </div>

          <div className="ev-section-card">
            <h4>About this recording</h4>
            <p>{recording.about}</p>
          </div>

          <div className="ev-section-card">
            <h4>Chapters</h4>
            <div className="rp-chapters">
              {recording.chapters.map((c, i) => (
                <button key={i} className={`rp-chapter-item${i === currentChapterIdx ? ' current' : ''}`} onClick={() => jumpToChapter(c.t)}>
                  <span className="ct">{fmtTime(c.t)}</span>
                  <span className="cl">{c.label}</span>
                  {i === currentChapterIdx && <span className="np">Now playing</span>}
                </button>
              ))}
            </div>
          </div>
        </div>

        <div className="ev-sidebar">
          <div className="ev-side-card">
            <h4>Up next</h4>
            {upNext.map((r) => (
              <button key={r.id} className="rp-upnext-item" onClick={() => onOpenUpNext(r.id)}>
                <div className="rp-upnext-thumb" style={{ background: UPNEXT_GRADIENTS[r.typeKey] || r.gradient, overflow: 'hidden' }}><VideoFrame /><span className="p" style={{ position: 'relative', zIndex: 1 }}><Icon name="play" size={10} color="#6700A6" /></span></div>
                <div className="rp-upnext-info"><div className="t">{r.title}</div><div className="s">{UPNEXT_LABEL[r.typeKey] || r.type} · {r.durationLabel}</div></div>
              </button>
            ))}
          </div>

          {recording.resources.length > 0 && (
            <div className="ev-side-card">
              <h4>Resources</h4>
              {recording.resources.map((res, i) => (
                <div className="rp-resource-item" key={i}>
                  <div className="rp-resource-icon">PDF</div>
                  <div className="rp-resource-info"><div className="n">{res.name}</div><div className="s">{res.size}</div></div>
                  <button className="rp-resource-dl" onClick={() => onDownloadResource(res.name)}><Icon name="download" size={15} color="currentColor" /></button>
                </div>
              ))}
            </div>
          )}

          <div className="ev-side-card ev-info-purple">
            <h4>Saved to Learning</h4>
            <p>This recording and its resources are saved to your Learning library so you can revisit them anytime.</p>
            <a onClick={() => onOpenUpNext(null)}>Go to Learning <Icon name="arrowRight" size={11} color="#6700A6" /></a>
          </div>
        </div>
      </div>
    </div>
  );
}

/* ============================================================
   Tour overlay
   ============================================================ */

const TOUR_STEPS = [
  { icon: 'wave', title: 'Welcome to Tribes Capital', desc: "You're now part of a community for people building and investing in clean energy. Let's show you around in 6 quick steps.", navKey: null },
  { icon: 'home', title: 'Your home', desc: "Your starting point. Tell us your goal here and we'll take you straight to the right place — contractors, learning, community and more.", navKey: 'home' },
  { icon: 'book', title: 'Your learning', desc: 'Build your knowledge of renewable energy at your own pace, from the basics through to advanced topics.', navKey: 'learning' },
  { icon: 'users', title: 'Community', desc: 'Ask questions, join discussions and share what you know with other members across the network.', navKey: 'community' },
  { icon: 'grid', title: 'Contractors', desc: 'Find and compare verified energy professionals, filtered by location and the service you need.', navKey: 'contractors' },
  { icon: 'message', title: 'Messaging', desc: "Message members directly once you've made a connection — introduce yourself and take it from there.", navKey: 'messaging' },
  { icon: 'shield', title: 'Due Diligence Vault', desc: 'Investor tool — access verified project documentation, audits and compliance materials to support your investment decisions.', navKey: 'vault' },
  { icon: 'briefcase', title: 'Project Pipeline', desc: 'Investor tool — track clean energy projects seeking investment, from early stage through to fully funded.', navKey: 'pipeline' },
  { icon: 'calendar', title: 'Office Hours & Events', desc: 'Investor tool — book time with the team, or join upcoming webinars and community events.', navKey: 'events' },
];

const SIDEBAR_WIDTH = 260;
const TOPBAR_HEIGHT = 65;
const TOUR_BREAKPOINT = 1024;

function TourOverlay({ step, navRefs, onNext, onBack, onSkip, onClose }) {
  const [pos, setPos] = useState({ centered: true, top: 0, left: 0, dimLeft: 0, dimTop: 0 });
  const cardRef = useRef(null);

  useLayoutEffect(() => {
    function compute() {
      const isNarrow = window.innerWidth < TOUR_BREAKPOINT;
      const data = TOUR_STEPS[step - 1];
      const cardH = cardRef.current ? cardRef.current.offsetHeight : 300;
      // Measure the real sidebar + top bar so the dim area lines up exactly with the content area
      const sb = document.querySelector('.dash-sidebar'), tb = document.querySelector('.dash-topbar');
      const sbRight = sb ? Math.round(sb.getBoundingClientRect().right) : SIDEBAR_WIDTH;
      const tbBottom = tb ? Math.round(tb.getBoundingClientRect().bottom) : TOPBAR_HEIGHT;
      const dimLeft = sbRight, dimTop = tbBottom;

      if (!data.navKey || isNarrow) {
        const contentLeft = isNarrow ? 0 : sbRight;
        const centerX = contentLeft + (window.innerWidth - contentLeft) / 2;
        const wantTop = Math.max(tbBottom + 24, window.innerHeight / 2 - cardH / 2);
        setPos({ centered: true, top: Math.max(8, Math.min(wantTop, window.innerHeight - cardH - 8)), left: centerX, dimLeft: isNarrow ? 0 : dimLeft, dimTop });
        return;
      }
      const navEl = navRefs.current[data.navKey];
      if (!navEl) { setPos({ centered: true, top: window.innerHeight / 2 - cardH / 2, left: dimLeft + (window.innerWidth - dimLeft) / 2, dimLeft, dimTop }); return; }
      const navRect = navEl.getBoundingClientRect();
      let left = sbRight + 24;
      let top = navRect.top - 18;
      const maxTop = window.innerHeight - cardH - 16;
      if (top > maxTop) top = maxTop;
      if (top < tbBottom + 12) top = tbBottom + 12;
      const pointerTop = Math.max(24, Math.min(navRect.top + navRect.height / 2 - top, cardH - 24));
      setPos({ centered: false, top, left, pointerTop, dimLeft, dimTop });
    }
    compute();
    const id = setTimeout(compute, 0);
    window.addEventListener('resize', compute);
    return () => { window.removeEventListener('resize', compute); clearTimeout(id); };
  }, [step, navRefs]);

  const data = TOUR_STEPS[step - 1];
  const isLast = step === TOUR_STEPS.length;
  const isFirst = step === 1;
  const cardStyle = pos.centered
    ? { top: pos.top, left: pos.left, transform: 'translateX(-50%)' }
    : { top: pos.top, left: pos.left };

  return (
    <>
      <div className="tour-click-block" />
      <div className="tour-dim" style={{ top: pos.dimTop || TOPBAR_HEIGHT, left: pos.dimLeft || 0, right: 0, bottom: 0 }} />
      <div className="tour-card" style={cardStyle} ref={cardRef}>
        {!pos.centered && <span className="tour-pointer" style={{ top: pos.pointerTop }} />}
        <button className="tour-close" onClick={onClose} aria-label="Close tour"><X size={13} color="#fff" strokeWidth={2.6} /></button>
        <div className="tour-top-row">
          <span className="tour-step-label">Step {step} of {TOUR_STEPS.length}</span>
          <button className="tour-skip" onClick={onSkip}>Skip tour</button>
        </div>
        <div className={`tour-icon${data.icon === 'wave' ? ' emoji' : ''}`}>
          {data.icon === 'wave' ? '👋' : <Icon name={data.icon} size={20} color="#5B21B6" />}
        </div>
        <h3 className="tour-title">{data.title}</h3>
        <p className="tour-desc">{data.desc}</p>
        <div className="tour-bottom-row">
          <div className="tour-dots">
            {TOUR_STEPS.map((_, i) => (<span key={i} className={`tour-dot${i + 1 === step ? ' active' : ''}`} />))}
          </div>
          <div className="tour-btns">
            {!isFirst && <button className="tour-back-btn" onClick={onBack}><ArrowLeft size={13} color="#374151" /> Back</button>}
            <button className="tour-next-btn" onClick={onNext}>{isLast ? 'Get started' : 'Next'} <ArrowRight size={13} color="#fff" /></button>
          </div>
        </div>
      </div>
    </>
  );
}

