const I = ({ d, s = 16 }) => <svg width={s} height={s} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round" style={{ flexShrink: 0 }}><path d={d} /></svg>;
const Ava = ({ c, t, s = 36 }) => <div className="ava" style={{ background: c, width: s, height: s, fontSize: s * 0.37 }}>{t}</div>;

/* ---------- shared UI ---------- */
const Modal = ({ onClose, children, w = 460 }) => <div className="ov" onClick={e => e.target === e.currentTarget && onClose()}><div className="md" style={{ maxWidth: w }}><button className="x" onClick={onClose} aria-label="Close"><X size={15} strokeWidth={2.4} /></button>{children}</div></div>;
const Drawer = ({ onClose, back, children, foot }) => <><div className="bk" onClick={onClose} /><aside className="dr"><div className="dt"><button className="lk" onClick={onClose}>← {back}</button><button className="x s" onClick={onClose} aria-label="Close"><X size={15} strokeWidth={2.4} /></button></div><div className="ds">{children}</div>{foot && <div className="df">{foot}</div>}</aside></>;

function FormModal({ title, sub, fields, cta, done, doneText, onClose, onSubmit, extra }) {
  const [v, setV] = useState(() => Object.fromEntries(fields.map(f => [f.k, f.o ? f.o[0] : ""])));
  const [sent, setSent] = useState(false);
  if (sent) return <Modal onClose={onClose}><div className="ok"><h3>{done}</h3><p className="sub">{doneText}</p>{extra}<button className="btn bp blk" onClick={onClose}>Done</button></div></Modal>;
  return <Modal onClose={onClose}>
    <h2>{title}</h2><p className="sub">{sub}</p>
    <div className="md-sub-divider" />
    {fields.map(f => <div className="fld" key={f.k}><label>{f.l}</label>
      {f.o ? <select value={v[f.k]} onChange={e => setV({ ...v, [f.k]: e.target.value })}>{f.o.map(o => <option key={o}>{o}</option>)}</select>
        : f.t === "area" ? <textarea placeholder={f.ph} value={v[f.k]} onChange={e => setV({ ...v, [f.k]: e.target.value })} />
        : <input type={f.t || "text"} placeholder={f.ph} value={v[f.k]} onChange={e => setV({ ...v, [f.k]: e.target.value })} />}</div>)}
    <div className="md-footer"><button className="btn bl" onClick={onClose}>Cancel</button><button className="btn bp" onClick={() => { onSubmit && onSubmit(v); setSent(true); }}>{cta}</button></div>
  </Modal>;
}

