  4: { role: "Learner", since: 2025, about: "Fatima is a learner working through the Tribes Capital courses on energy fundamentals. She shares study notes with the community and is exploring a career in clean energy.", interests: ["Energy Fundamentals", "Renewable Energy", "Sustainable Development"], info: [["Role", "Learner"], ["Location", "Nigeria"], ["Member since", "2025"], ["Courses in progress", "3"]] },
