function MemberProfilePage({ t, onBack, onMessage }) {
  const d = MEM[t.id] || { role: t.r, since: 2025, about: "Member of the Tribes Capital energy community.", interests: [], info: [["Role", t.r], ["Member since", "2025"]] };
  useEffect(() => { window.scrollTo(0, 0); }, [t.id]);
  return (
    <div className="cp cp-mem">
      <button className="cp-back" onClick={onBack}><svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round"><path d="M19 12H5M11 6l-6 6 6 6" /></svg>Back to messages</button>
      <div className="cp-lay">
        <div className="cp-main">
          <section className="cp-card">
            <div className="cp-head">
              <div className="cp-logo" aria-hidden="true" style={{ background: t.c }}>{t.n[0]}</div>
              <div className="cp-id">
                <div className="cp-name"><h1>{t.n}</h1></div>
                <p className="cp-role" style={{ color: "#6B7280" }}>{d.role}</p>
                <div className="cp-meta"><span><span className={"status-dot" + (t.online ? " on" : "")} />{t.online ? "Online" : "Offline"}</span><span>Member since {d.since}</span></div>
              </div>
              <div className="cp-acts"><button className="cp-btn fill" onClick={onMessage}>Message</button></div>
            </div>
          </section>
          <section className="cp-card cp-about"><h3>About</h3><p>{d.about}</p></section>
          {d.interests.length > 0 && <section className="cp-card"><h3>Interests</h3><div className="cp-chips">{d.interests.map(x => <span className="cp-chip" key={x}>{x}</span>)}</div></section>}
        </div>
        <aside className="cp-rail">
          <section className="cp-card"><h3>Member information</h3>
            <div className="cp-info">{d.info.map(([l, v]) => <div className="cp-row" key={l}>{l}<b>{v}</b></div>)}</div>
          </section>
        </aside>
      </div>
    </div>
  );
}

function Messaging({ toast }) {
  const [th, setTh] = useState(THREADS0), [cur, setCur] = useState(1), [txt, setTxt] = useState(""), [view, setView] = useState(false);
  const [q, setQ] = useState(""), [prof, setProf] = useState(false);
  const t = th.find(x => x.id === cur);
  const bodyRef = useRef(null);
  useEffect(() => { const el = bodyRef.current; if (el) el.scrollTop = el.scrollHeight; }, [cur, t.m.length, view, prof]);
  const filtered = th.filter(x => !q || x.n.toLowerCase().includes(q.toLowerCase()));
  const send = () => {
    if (!txt.trim()) return;
    setTh(th.map(x => x.id === cur ? { ...x, m: [...x.m, ["me", txt.trim(), "Now"]], preview: undefined, unread: false } : x));
    setTxt("");
  };
  const openThread = (id) => { setTh(th.map(x => x.id === id ? { ...x, unread: false } : x)); setCur(id); setView(true); };
  const pc = t.contractorId ? CON.find(c => c.id === t.contractorId) : null;
  if (prof && !t.isGroup) return pc
    ? <ContractorProfilePage pc={pc} backLabel="Back to messages" onBack={() => setProf(false)} onMessage={() => setProf(false)} onContact={() => { setProf(false); toast && toast(`You're already connected with ${pc.n} in Messaging.`); }} />
    : <MemberProfilePage t={t} onBack={() => setProf(false)} onMessage={() => setProf(false)} />;
  return <>
    <div className={"msg" + (view ? " thread" : "")}>
      <div className="ml">
        <div className="ml-head"><h2>Messages</h2>
          <div className="ml-search"><Search size={15} color="#9CA3AF" /><input placeholder="Search messages" value={q} onChange={e => setQ(e.target.value)} aria-label="Search messages" /></div>
        </div>
        <div className="ml-list">
          {filtered.map(x => <button key={x.id} className={"mi" + (x.id === cur ? " on" : "") + (x.unread ? " unread" : "")} onClick={() => openThread(x.id)}>
            <Ava c={x.c} t={x.n[0]} s={40} />
            <div className="sp">
              <div className="row" style={{ justifyContent: "space-between" }}><b style={{ fontSize: 14 }}>{x.n}</b><span className="mi-time">{x.time}</span></div>
              <div className="row" style={{ justifyContent: "space-between", gap: 8 }}><span className="mut mi-preview">{x.preview || x.m[x.m.length - 1][1]}</span>{x.unread && <span className="mi-dot" />}</div>
            </div>
          </button>)}
          {filtered.length === 0 && <div className="sub" style={{ padding: "24px 20px" }}>No conversations match "{q}".</div>}
        </div>
      </div>
      <div className="mt2">
        <div className="mh">
          <button className="lk mback" onClick={() => setView(false)}>← Back</button>
          <Ava c={t.c} t={t.n[0]} s={38} />
          <div className="sp"><b style={{ fontSize: 14.5 }}>{t.n}</b>
            <div className="mut row" style={{ gap: 6 }}>{!t.isGroup && <span className={"status-dot" + (t.online ? " on" : "")} />}{t.isGroup ? t.r : `${t.online ? "Online" : "Offline"} · ${t.r}`}</div>
          </div>
          {!t.isGroup && <button className="btn bo sm" onClick={() => setProf(true)}>View profile</button>}
        </div>
        <div className="mb" ref={bodyRef}>
          <div className="mb-date"><span>Today</span></div>
          {t.m.map((x, i) => <div key={i} title={x[2]} className={"bub" + (x[0] === "me" ? " me" : "")}>{x[1]}</div>)}
        </div>
        <div className="mf"><input placeholder="Write a message…" aria-label="Write a message" value={txt} onChange={e => setTxt(e.target.value)} onKeyDown={e => e.key === "Enter" && send()} /><button className="btn bp" onClick={send}>Send</button></div>
      </div>
    </div>
  </>;
}

/* ============================================================
   Main app component
   ============================================================ */

const ROLES = ['Homeowner', 'Energy professional', 'Learner', 'Business owner'];
const INTERESTS = [
  'Solar Energy', 'Battery Storage', 'Home Solar', 'Sustainability',
  'Wind Energy', 'Energy Efficiency', 'Renewable Policy', 'Electric Mobility',
  'Clean Cooking', 'Mini-grids', 'Energy Careers', 'Community Projects',
];

function maskEmail(email) {
  const [user, domain] = (email || '').split('@');
  if (!domain || !user) return email || 'you@email.com';
  if (user.length <= 2) return `${user[0]}***@${domain}`;
  return `${user[0]}***${user[user.length - 1]}@${domain}`;
}

function initialCourseProgress() {
  const init = {};
  COURSES.forEach((c) => { init[c.id] = { started: false, completed: 0, percent: 0 }; });
  init['renewable-basics'] = { started: true, completed: 3, percent: 62 };
  return init;
}

export default function TribesCapitalApp({ initialScreen = 'signin', user: authenticatedUser, onLogout: onAuthenticatedLogout } = {}) {
  const [screen, setScreen] = useState(initialScreen);
  const [toastMsg, setToastMsg] = useState(null);
  const toastTimer = useRef(null);

  // Make sure mobile browsers render at device width and let the layout extend under notches
  useEffect(() => {
    let m = document.querySelector('meta[name="viewport"]');
    if (!m) { m = document.createElement('meta'); m.name = 'viewport'; document.head.appendChild(m); }
    m.content = 'width=device-width, initial-scale=1, viewport-fit=cover';
  }, []);

  // Dashboard / tour
  const navRefs = useRef({});
  const sidebarRef = useRef(null);
  const [tourOpen, setTourOpen] = useState(false);
  const [tourStep, setTourStep] = useState(1);
  const [tourSeen, setTourSeen] = useState(false);

  // Learning
  const [courseProgress, setCourseProgress] = useState(initialCourseProgress);
  const [currentCourseId, setCurrentCourseId] = useState(null);
  const [learningFilter, setLearningFilter] = useState('All topics');
  const [learningSort, setLearningSort] = useState('Progress');
  const [sortMenuOpen, setSortMenuOpen] = useState(false);
  const [reviewOpen, setReviewOpen] = useState(false);

  // Events
  const [registrations, setRegistrations] = useState({ 'ask-contractor-solar': true, 'sizing-solar-storage': true });
  const [followingHosts, setFollowingHosts] = useState({});
  const [watchedRecordingIds, setWatchedRecordingIds] = useState({ 'solar-basics-panels-power': true, 'choosing-right-inverter': true });
  const [likedRecordingIds, setLikedRecordingIds] = useState({});
  const [savedRecordingIds, setSavedRecordingIds] = useState({});
  const [currentEventId, setCurrentEventId] = useState(null);
  const [currentRecordingId, setCurrentRecordingId] = useState(null);
  const [eventsFilter, setEventsFilter] = useState('All events');
  const [pastEventsFilter, setPastEventsFilter] = useState('All recordings');
  const [registerModalEventId, setRegisterModalEventId] = useState(null);
  const [calendarModalEventId, setCalendarModalEventId] = useState(null);
  const [cancelModalEventId, setCancelModalEventId] = useState(null);
  const [shareModalEventId, setShareModalEventId] = useState(null);

  const [contractorQ, setContractorQ] = useState('');
  const [contractorProfId, setContractorProfId] = useState(null);
  const [hostModal, setHostModal] = useState(null);
  const [communityOpen, setCommunityOpen] = useState(null);

  const [siEmail, setSiEmail] = useState('');
  const [siPassword, setSiPassword] = useState('');
  const [siShowPwd, setSiShowPwd] = useState(false);
  const [siKeep, setSiKeep] = useState(false);

  const [caName, setCaName] = useState('');
  const [caEmail, setCaEmail] = useState('');
  const [caPassword, setCaPassword] = useState('');
  const [caShowPwd, setCaShowPwd] = useState(false);

  const [otp, setOtp] = useState(['', '', '', '', '', '']);
  const otpRefs = useRef([]);
  const [resendSeconds, setResendSeconds] = useState(28);

  const [pfName, setPfName] = useState('');
  const [pfLocation, setPfLocation] = useState('');
  const [pfRole, setPfRole] = useState(null);
  const [pfBio, setPfBio] = useState('');
  const [pfPhoto, setPfPhoto] = useState(null);
  const photoInputRef = useRef(null);

  const [interests, setInterests] = useState([]);

  // Profile page: values the person edits on the Profile screen (null until first save).
  const [profileEdits, setProfileEdits] = useState(null);
  const profileReturn = useRef('dashboard');   // screen to go back to when the profile is closed

  const [fpEmail, setFpEmail] = useState('');
  const [rpNew, setRpNew] = useState('');
  const [rpConfirm, setRpConfirm] = useState('');
  const [rpShowNew, setRpShowNew] = useState(false);
  const [rpShowConfirm, setRpShowConfirm] = useState(false);

  function navigate(next) {
    if (next === 'profile' && screen !== 'profile') profileReturn.current = screen;
    setScreen(next);
    window.scrollTo(0, 0);
    // First-time users land on Home and are greeted by the guided tour (Step 1 of 9)
    if (next === 'dashboard' && !tourSeen) {
      setTourStep(1);
      setTourSeen(true);
      setTimeout(() => setTourOpen(true), 250);
    }
  }
  function showToast(msg) {
    setToastMsg(msg);
    if (toastTimer.current) clearTimeout(toastTimer.current);
    toastTimer.current = setTimeout(() => setToastMsg(null), 3000);
  }

  useEffect(() => {
    if (screen !== 'verify-email') return undefined;
    setResendSeconds(28);
    const id = setInterval(() => setResendSeconds((s) => (s > 0 ? s - 1 : 0)), 1000);
    return () => clearInterval(id);
  }, [screen]);

  useEffect(() => () => { if (toastTimer.current) clearTimeout(toastTimer.current); }, []);

  const signInValid = siEmail.includes('@') && siPassword.length > 0;
  const createValid = caName.trim().length > 0 && caEmail.includes('@') && caPassword.length >= 6;
  const forgotValid = fpEmail.includes('@');
  const pwdLenOk = rpNew.length >= 8;
  const pwdCaseOk = /[a-z]/.test(rpNew) && /[A-Z]/.test(rpNew);
  const pwdNumOk = /[0-9]/.test(rpNew);
  const resetValid = pwdLenOk && pwdCaseOk && pwdNumOk && rpConfirm.length > 0 && rpNew === rpConfirm;

  function handleOtpChange(i, val) {
    if (!/^[0-9]?$/.test(val)) return;
    const next = [...otp];
    next[i] = val;
    setOtp(next);
    if (val && i < 5) { const el = otpRefs.current[i + 1]; if (el) el.focus(); }
  }
  function handleOtpKeyDown(i, e) {
    if (e.key === 'Backspace' && !otp[i] && i > 0) { const el = otpRefs.current[i - 1]; if (el) el.focus(); }
  }
  const otpComplete = otp.every((d) => d !== '');

  function handlePhotoChange(e) {
    const file = e.target.files && e.target.files[0];
    if (!file) return;
    setPfPhoto(URL.createObjectURL(file));
  }
  function toggleInterest(label) {
    setInterests((prev) => (prev.includes(label) ? prev.filter((x) => x !== label) : [...prev, label]));
  }

  function handleSignIn() { if (signInValid) navigate('dashboard'); }
  function handleCreateAccount() { if (createValid) navigate('verify-email'); }
  function handleVerifyEmail() { if (otpComplete) navigate('complete-profile'); }
  function handleResendCode() { if (resendSeconds > 0) return; setResendSeconds(28); showToast('A new code has been sent'); }
  function finishOnboarding() { navigate('dashboard'); }
  function handleForgotSubmit() { if (forgotValid) navigate('check-email'); }
  function handleResendLink() { showToast('Reset link resent'); }
  function handleOpenEmailApp() {
    showToast('Opening your email app…');
    try { window.location.href = 'mailto:'; } catch (e) { /* no-op in sandboxed preview */ }
    setTimeout(() => navigate('reset-password'), 1200);
  }
  function handleResetPassword() { if (resetValid) navigate('reset-success'); }

  function tourNext() {
    if (tourStep >= TOUR_STEPS.length) { setTourOpen(false); return; }
    setTourStep((s) => s + 1);
  }
  function tourBack() { setTourStep((s) => Math.max(1, s - 1)); }
  function tourSkip() { setTourOpen(false); }
  function reopenTour() { setTourStep(1); setTourOpen(true); }
  function openHelp() { navigate('help'); }

  const PAGES = ['learning', 'events', 'community', 'contractors', 'messaging', 'vault', 'pipeline', 'settings'];
  function handleSidebarNav(key) {
    const [k, arg] = key.split(':');
    if (k === 'home') { navigate('dashboard'); return; }
    if (!PAGES.includes(k)) return;
    if (k === 'community') setCommunityOpen(arg || null);
    if (k === 'contractors') { setContractorQ(''); setContractorProfId(null); }
    navigate(k);
  }
  function goApp(k, query = '') { setContractorQ(query); setContractorProfId(null); if (k === 'contractors') { navigate('contractors'); } else handleSidebarNav(k); }
  function searchContractors(query) { setContractorQ(query); setContractorProfId(null); navigate('contractors'); }
  function viewHostProfile(host) {
    const c = CON.find((x) => x.n === host.name);
    if (c) { setContractorQ(''); setContractorProfId(c.id); navigate('contractors'); }   // contractor hosts → full contractor profile
    else setHostModal(host);                                                              // everyone else → host profile card
  }
  function logOut() {
    setTourOpen(false);
    if (onAuthenticatedLogout) {
      onAuthenticatedLogout();
      return;
    }
    navigate('signin');
    showToast('You have been logged out');
  }

  /* ---------------- Events handlers ---------------- */
  function openEvent(id) { setCurrentEventId(id); navigate('event-detail'); }
  function registerForEvent(id) {
    setRegistrations((prev) => ({ ...prev, [id]: true }));
    setRegisterModalEventId(id);
  }
  function requestCancelRegistration(id) { setCancelModalEventId(id); }
  function confirmCancelRegistration() {
    setRegistrations((prev) => { const next = { ...prev }; delete next[cancelModalEventId]; return next; });
    setCancelModalEventId(null);
    showToast('Registration cancelled');
  }
  function toggleFollowHost(key) {
    setFollowingHosts((prev) => ({ ...prev, [key]: !prev[key] }));
  }
  function openRecording(id) {
    if (!id) { navigate('learning'); return; }
    setCurrentRecordingId(id);
    navigate('recording-player');
  }
  function toggleLikeRecording() {
    setLikedRecordingIds((prev) => ({ ...prev, [currentRecordingId]: !prev[currentRecordingId] }));
  }
  function toggleSaveRecording() {
    setSavedRecordingIds((prev) => ({ ...prev, [currentRecordingId]: !prev[currentRecordingId] }));
    showToast(savedRecordingIds[currentRecordingId] ? 'Removed from Saved' : 'Saved — find it under My Events');
  }
  function markRecordingWatched(id) {
    setWatchedRecordingIds((prev) => (prev[id] ? prev : { ...prev, [id]: true }));
  }
  function handleCalendarOption(kind, event) {
    if (kind === 'ics') { downloadIcs(event); showToast('Downloading ' + event.id + '.ics'); }
    else { const labels = { google: 'Google Calendar', outlook: 'Outlook Calendar', apple: 'Apple Calendar' }; showToast('Opening ' + labels[kind] + '\u2026'); }
  }
  function handleShareOption(kind, event) {
    const url = encodeURIComponent(`https://tribescapital.com/events/${event.id}`);
    const text = encodeURIComponent(event.title);
    let href = null;
    if (kind === 'email') href = `mailto:?subject=${text}&body=${url}`;
    else if (kind === 'whatsapp') href = `https://wa.me/?text=${text}%20${url}`;
    else if (kind === 'linkedin') href = `https://www.linkedin.com/sharing/share-offsite/?url=${url}`;
    else if (kind === 'x') href = `https://twitter.com/intent/tweet?text=${text}&url=${url}`;
    if (href) { try { window.open(href, '_blank', 'noopener'); } catch (e) { /* ignore */ } }
    showToast('Opening share link\u2026');
  }
  function handleDownloadResource(name) { showToast('Downloading ' + name + '\u2026'); }

  function handleSaveCourse() { navigate('course-saved'); }

  /* ---------------- Learning handlers ---------------- */
  function getCourse(id) { return COURSES.find((c) => c.id === id); }
  function getStatus(id) {
    const c = getCourse(id); const p = courseProgress[id];
    if (!c || !p) return 'not-started';
    if (p.completed >= c.lessons.length) return 'completed';
    if (p.started) return 'in-progress';
    return 'not-started';
  }
  function openCourse(id) { setCurrentCourseId(id); navigate('course-detail'); }
  function handleStartCourse() {
    setCourseProgress((prev) => ({ ...prev, [currentCourseId]: { ...prev[currentCourseId], started: true } }));
  }
  function handleContinueLesson() {
    const c = getCourse(currentCourseId);
    setCourseProgress((prev) => {
      const cur = prev[currentCourseId] || { started: true, completed: 0, percent: 0 };
      const nextCompleted = Math.min(cur.completed + 1, c.lessons.length);
      const nextPercent = Math.round((nextCompleted / c.lessons.length) * 100);
      return { ...prev, [currentCourseId]: { started: true, completed: nextCompleted, percent: nextPercent } };
    });
  }
  function handleStartAgain() {
    setCourseProgress((prev) => ({ ...prev, [currentCourseId]: { started: true, completed: 0, percent: 0 } }));
  }

  const uName = pfName.trim() || caName.trim() || (siEmail.includes('@') ? siEmail.split('@')[0] : '') || 'Ali Bello';
  const fallbackUser = { name: uName, initial: uName[0].toUpperCase(), email: caEmail || siEmail || 'ali.bello@email.com', location: pfLocation.trim() || 'Lagos, Nigeria', city: (pfLocation.trim() || 'Lagos').split(',')[0] };
  const userName = authenticatedUser?.name || authenticatedUser?.firstName || authenticatedUser?.email?.split('@')[0] || fallbackUser.name;
  const user = {
    ...fallbackUser,
    ...authenticatedUser,
    name: userName,
    initial: userName[0]?.toUpperCase() || fallbackUser.initial,
    email: authenticatedUser?.email || fallbackUser.email,
    location: authenticatedUser?.location || fallbackUser.location,
    city: authenticatedUser?.city || authenticatedUser?.location?.split(',')[0] || fallbackUser.city,
  };
  const DEFAULT_TAGLINE = 'Homeowner · Exploring solar & renewable energy';
  const DEFAULT_BIO = 'Homeowner in Lagos exploring solar and battery storage to deal with frequent grid outages. Interested in learning the fundamentals, connecting with verified contractors, and eventually helping neighbours make the switch to clean energy.';
  const DEFAULT_INTERESTS = ['Solar Energy', 'Battery Storage', 'Renewable Energy', 'Energy Efficiency', 'Clean Energy', 'Sustainability'];
  const profile = {
    tagline: profileEdits ? profileEdits.tagline : (pfRole ? `${pfRole} · Exploring solar & renewable energy` : DEFAULT_TAGLINE),
    bio: profileEdits ? profileEdits.bio : (pfBio.trim() || DEFAULT_BIO),
    interests: profileEdits ? profileEdits.interests : (interests.length ? interests : DEFAULT_INTERESTS),
    social: profileEdits ? profileEdits.social : '',
    interestsDone: profileEdits ? profileEdits.interestsDone : false,
  };
  function saveProfile(v) {
    setPfName(v.name);
    setPfLocation(v.location);
    setProfileEdits({ tagline: v.tagline, bio: v.bio, interests: v.interests, social: v.social, interestsDone: true });
    showToast('Profile updated');
  }
  function closeProfile() {
    const back = profileReturn.current;
    navigate(back && back !== 'profile' ? back : 'dashboard');
  }
  const shellProps = { onSearch: searchContractors, onLogout: logOut, onOpenProfile: () => navigate('profile'), user };
  let bodyEl = null;

  if (screen === 'signin') {
    bodyEl = (
      <AuthShell leftHeading="Welcome back to the clean energy community.">
        <h1 className="tca-h1">Welcome back</h1>
        <p className="tca-sub">Sign in to continue your clean energy journey.</p>
        <Field label="Email address" type="email" value={siEmail} onChange={(e) => setSiEmail(e.target.value)} placeholder="you@email.com" autoComplete="email" />
        <PasswordField label="Password" value={siPassword} onChange={(e) => setSiPassword(e.target.value)} placeholder="Enter your password" show={siShowPwd} onToggle={() => setSiShowPwd((s) => !s)} autoComplete="current-password" />
        <div className="tca-row-between">
          <label className="tca-checkbox">
            <input type="checkbox" checked={siKeep} onChange={(e) => setSiKeep(e.target.checked)} style={{ accentColor: '#5B21B6' }} />
            Keep me signed in
          </label>
          <button type="button" className="tca-link" onClick={() => navigate('forgot-password')}>Forgot password?</button>
        </div>
        <PrimaryButton enabled={signInValid} onClick={handleSignIn}>Sign in</PrimaryButton>
        <Divider />
        <GoogleButton onClick={() => navigate('dashboard')}>Continue with Google</GoogleButton>
        <p className="tca-footer-text">
          New to Tribes Capital? <button type="button" className="tca-link" onClick={() => navigate('create-account')}>Create an account</button>
        </p>
      </AuthShell>
    );
  } else if (screen === 'create-account') {
    bodyEl = (
      <AuthShell leftHeading="Join the clean energy community.">
        <StepDots current={1} />
        <h1 className="tca-h1">Create your account</h1>
        <p className="tca-sub">Start your clean energy journey in a couple of minutes.</p>
        <Field label="Full name" value={caName} onChange={(e) => setCaName(e.target.value)} placeholder="Enter your full name" autoComplete="name" />
        <Field label="Email address" type="email" value={caEmail} onChange={(e) => setCaEmail(e.target.value)} placeholder="you@email.com" autoComplete="email" />
        <PasswordField label="Password" value={caPassword} onChange={(e) => setCaPassword(e.target.value)} placeholder="Create a password" show={caShowPwd} onToggle={() => setCaShowPwd((s) => !s)} autoComplete="new-password" />
        <div style={{ marginTop: 6 }}>
          <PrimaryButton enabled={createValid} onClick={handleCreateAccount}>Create account</PrimaryButton>
        </div>
        <Divider />
        <GoogleButton onClick={() => navigate('dashboard')}>Continue with Google</GoogleButton>
        <p className="tca-footer-text">
          Already have an account? <button type="button" className="tca-link" onClick={() => navigate('signin')}>Sign in</button>
        </p>
      </AuthShell>
    );
  } else if (screen === 'verify-email') {
    const mm = Math.floor(resendSeconds / 60);
    const ss = String(resendSeconds % 60).padStart(2, '0');
    bodyEl = (
      <AuthShell leftHeading="One quick check.">
        <h1 className="tca-h1">Verify your email</h1>
        <p className="tca-sub">We sent a 6-digit code to {caEmail || 'you@email.com'}. Enter it below to confirm your account.</p>
        <div className="tca-otp-row">
          {otp.map((digit, i) => (
            <input
              key={i}
              ref={(el) => { otpRefs.current[i] = el; }}
              value={digit}
              onChange={(e) => handleOtpChange(i, e.target.value)}
              onKeyDown={(e) => handleOtpKeyDown(i, e)}
              inputMode="numeric"
              pattern="[0-9]*"
              maxLength={1}
              className="tca-otp-box"
            />
          ))}
        </div>
        <PrimaryButton enabled={otpComplete} onClick={handleVerifyEmail}>Verify email</PrimaryButton>
        <p className="tca-footer-text" style={{ marginTop: 20 }}>
          Didn't get a code?{' '}
          {resendSeconds > 0 ? (
            <span style={{ color: '#9CA3AF' }}>Resend in {mm}:{ss}</span>
          ) : (
            <button type="button" className="tca-link" onClick={handleResendCode}>Resend code</button>
          )}
        </p>
        <BackLink onClick={() => navigate('create-account')}>Change email address</BackLink>
      </AuthShell>
    );
  } else if (screen === 'complete-profile') {
    bodyEl = (
      <OnboardingShell onSkip={finishOnboarding}>
        <StepDots current={2} />
        <h1 className="tca-onboard-h1">Complete your profile</h1>
        <p className="tca-onboard-sub">Add a few details so the community and contractors can get to know you.</p>
        <div className="tca-photo-wrap">
          <input ref={photoInputRef} type="file" accept="image/*" onChange={handlePhotoChange} style={{ display: 'none' }} />
          <button type="button" className="tca-photo-btn" onClick={() => photoInputRef.current && photoInputRef.current.click()}>
            {pfPhoto ? <img src={pfPhoto} alt="Profile preview" /> : <Camera size={19} color="#5B21B6" />}
          </button>
          <button type="button" className="tca-photo-label" onClick={() => photoInputRef.current && photoInputRef.current.click()}>
            {pfPhoto ? 'Change photo' : 'Add a photo'}
          </button>
        </div>
        <div className="tca-onboard-inner">
          <Field label="Full name" value={pfName} onChange={(e) => setPfName(e.target.value)} placeholder="Enter your full name" />
          <Field label="Location" value={pfLocation} onChange={(e) => setPfLocation(e.target.value)} placeholder="Enter your location" />
          <div style={{ marginBottom: 16 }}>
            <label className="tca-fieldset-label">I'm here as a...</label>
            <div className="tca-pills">
              {ROLES.map((r) => (<Pill key={r} label={r} selected={pfRole === r} onClick={() => setPfRole(r)} />))}
            </div>
          </div>
          <div className="tca-field" style={{ marginBottom: 30 }}>
            <label>Short bio</label>
            <textarea value={pfBio} onChange={(e) => setPfBio(e.target.value)} placeholder="Write your bio" rows={4} />
          </div>
          <div className="tca-btn-row">
            <OutlineButton onClick={() => navigate('create-account')}>Back</OutlineButton>
            <PrimaryButton enabled onClick={() => navigate('interests')} icon={<ArrowRight size={16} color="#fff" />}>Continue</PrimaryButton>
          </div>
        </div>
      </OnboardingShell>
    );
  } else if (screen === 'interests') {
    bodyEl = (
      <OnboardingShell onSkip={finishOnboarding}>
        <StepDots current={3} />
        <h1 className="tca-onboard-h1">What are you interested in?</h1>
        <p className="tca-onboard-sub">Pick a few topics and we will personalise your home, learning and community feed. You can change these anytime.</p>
        <div className="tca-onboard-inner wide">
          <div className="tca-pills center" style={{ marginBottom: 30 }}>
            {INTERESTS.map((topic) => (<Pill key={topic} label={topic} selected={interests.includes(topic)} onClick={() => toggleInterest(topic)} />))}
          </div>
          <div className="tca-btn-row">
            <OutlineButton onClick={() => navigate('complete-profile')}>Back</OutlineButton>
            <PrimaryButton enabled onClick={finishOnboarding} icon={<ArrowRight size={16} color="#fff" />}>Continue</PrimaryButton>
          </div>
        </div>
      </OnboardingShell>
    );
  } else if (screen === 'forgot-password') {
    bodyEl = (
      <AuthShell leftHeading="Let's get you back in.">
        <h1 className="tca-h1">Forgot your password?</h1>
        <p className="tca-sub">Enter the email linked to your account and we'll send you a link to reset your password.</p>
        <Field label="Email address" type="email" value={fpEmail} onChange={(e) => setFpEmail(e.target.value)} placeholder="you@email.com" autoComplete="email" />
        <div style={{ marginTop: 6 }}>
          <PrimaryButton enabled={forgotValid} onClick={handleForgotSubmit}>Send reset link</PrimaryButton>
        </div>
        <BackLink onClick={() => navigate('signin')}>Back to sign in</BackLink>
      </AuthShell>
    );
  } else if (screen === 'check-email') {
    bodyEl = (
      <AuthShell leftHeading="Almost there.">
        <div className="tca-mail-icon"><span><Mail size={24} color="#5B21B6" /></span></div>
        <h1 className="tca-h1">Check your email</h1>
        <p className="tca-sub">We've sent a password reset link to {maskEmail(fpEmail)}. Click the link in the email to choose a new password.</p>
        <PrimaryButton enabled onClick={handleOpenEmailApp}>Open email app</PrimaryButton>
        <p className="tca-footer-text">
          Didn't get the email? <button type="button" className="tca-link" onClick={handleResendLink}>Resend link</button>
        </p>
        <BackLink onClick={() => navigate('signin')}>Back to sign in</BackLink>
      </AuthShell>
    );
  } else if (screen === 'reset-password') {
    bodyEl = (
      <AuthShell leftHeading="Set a fresh password.">
        <h1 className="tca-h1">Create a new password</h1>
        <p className="tca-sub">Choose a strong password you haven't used before.</p>
        <PasswordField label="New password" value={rpNew} onChange={(e) => setRpNew(e.target.value)} placeholder="Create a password" show={rpShowNew} onToggle={() => setRpShowNew((s) => !s)} autoComplete="new-password" />
        <PasswordField label="Confirm password" value={rpConfirm} onChange={(e) => setRpConfirm(e.target.value)} placeholder="Re-enter new password" show={rpShowConfirm} onToggle={() => setRpShowConfirm((s) => !s)} autoComplete="new-password" />
        <div className="tca-req-list">
          <ReqItem met={pwdLenOk}>At least 8 characters</ReqItem>
          <ReqItem met={pwdCaseOk}>One uppercase and one lowercase letter</ReqItem>
          <ReqItem met={pwdNumOk}>At least one number</ReqItem>
        </div>
        <PrimaryButton enabled={resetValid} onClick={handleResetPassword}>Reset password</PrimaryButton>
        <BackLink onClick={() => navigate('signin')}>Back to sign in</BackLink>
      </AuthShell>
    );
  } else if (screen === 'reset-success') {
    bodyEl = (
      <AuthShell leftHeading="You're all set." showLogo={false}>
        <h1 className="tca-success-h1">Password updated</h1>
        <p className="tca-success-sub">Your password has been changed successfully. You can now sign in with your new password.</p>
        <PrimaryButton enabled onClick={() => navigate('signin')}>Back to sign in</PrimaryButton>
      </AuthShell>
    );
  } else if (screen === 'course-saved') {
    bodyEl = (
      <AuthShell leftHeading="Nice work." showLogo={false}>
        <h1 className="tca-success-h1">Progress saved</h1>
        <p className="tca-success-sub">Your completed course has been saved to your learning history. You can revisit it anytime from Learning.</p>
        <PrimaryButton enabled onClick={() => navigate('learning')}>Back to Learning</PrimaryButton>
      </AuthShell>
    );
  } else if (screen === 'dashboard') {
    bodyEl = (
      <AppShell navRefs={navRefs} sidebarRef={sidebarRef} onOpenHelp={openHelp} activeKey="home" onNavigate={handleSidebarNav} {...shellProps}>
        <DashboardHomeContent onGo={handleSidebarNav} />
      </AppShell>
    );
  } else if (screen === 'learning') {
    bodyEl = (
      <AppShell navRefs={navRefs} sidebarRef={sidebarRef} onOpenHelp={openHelp} activeKey="learning" onNavigate={handleSidebarNav} {...shellProps}>
        <LearningList
          progress={courseProgress}
          filter={learningFilter} setFilter={setLearningFilter}
          sort={learningSort} setSort={setLearningSort}
          sortMenuOpen={sortMenuOpen} setSortMenuOpen={setSortMenuOpen}
          onOpenCourse={openCourse}
        />
      </AppShell>
    );
  } else if (screen === 'course-detail' && currentCourseId) {
    const course = getCourse(currentCourseId);
    const progress = courseProgress[currentCourseId] || { started: false, completed: 0, percent: 0 };
    const status = getStatus(currentCourseId);
    const related = COURSES.filter((c) => c.id !== currentCourseId).slice(0, 3);
    bodyEl = (
      <AppShell navRefs={navRefs} sidebarRef={sidebarRef} onOpenHelp={openHelp} activeKey="learning" onNavigate={handleSidebarNav} {...shellProps}>
        <CourseDetail
          course={course} progress={progress} status={status}
          onStart={handleStartCourse} onContinue={handleContinueLesson}
          onStartAgain={handleStartAgain} onSave={handleSaveCourse}
          onOpenReview={() => setReviewOpen(true)}
          onBack={() => navigate('learning')}
          related={related} onOpenRelated={openCourse}
        />
        {reviewOpen && <ReviewModal course={course} onClose={() => setReviewOpen(false)} />}
      </AppShell>
    );
  } else if (screen === 'events') {
    bodyEl = (
      <AppShell navRefs={navRefs} sidebarRef={sidebarRef} onOpenHelp={openHelp} activeKey="events" onNavigate={handleSidebarNav} {...shellProps}>
        <EventsList
          registrations={registrations}
          followingHosts={followingHosts}
          filter={eventsFilter} setFilter={setEventsFilter}
          onOpenEvent={openEvent}
          onRegister={registerForEvent}
          onToggleFollow={toggleFollowHost}
          onOpenCalendarFor={(id) => setCalendarModalEventId(id)}
          onGoRecordings={() => navigate('past-events')}
          onGoMyEvents={() => navigate('my-events')}
          onNotify={() => showToast('You\u2019ll be notified when new events are added')}
        />
      </AppShell>
    );
  } else if (screen === 'event-detail' && currentEventId) {
    const event = findEvent(currentEventId);
    bodyEl = (
      <AppShell navRefs={navRefs} sidebarRef={sidebarRef} onOpenHelp={openHelp} activeKey="events" onNavigate={handleSidebarNav} {...shellProps}>
        <EventDetail
          event={event}
          registered={!!registrations[event.id]}
          onBack={() => navigate('events')}
          onRegister={() => registerForEvent(event.id)}
          onOpenCalendar={() => setCalendarModalEventId(event.id)}
          onOpenShare={() => setShareModalEventId(event.id)}
          onOpenRelated={openEvent}
          onViewHostProfile={() => viewHostProfile(event.host)}
        />
        {hostModal && (
          <HostProfileModal
            host={hostModal}
            currentEventId={event.id}
            following={!!followingHosts[hostKeyFor(hostModal.name)]}
            onToggleFollow={() => toggleFollowHost(hostKeyFor(hostModal.name))}
            onOpenEvent={(id) => { setHostModal(null); openEvent(id); }}
            onClose={() => setHostModal(null)}
          />
        )}
      </AppShell>
    );
  } else if (screen === 'my-events') {
    bodyEl = (
      <AppShell navRefs={navRefs} sidebarRef={sidebarRef} onOpenHelp={openHelp} activeKey="events" onNavigate={handleSidebarNav} {...shellProps}>
        <MyEvents
          registrations={registrations}
          savedRecordingIds={savedRecordingIds}
          watchedIds={watchedRecordingIds}
          onBack={() => navigate('events')}
          onGoAllEvents={() => navigate('events')}
          onGoPastEvents={() => navigate('past-events')}
          onJoin={(e) => showToast('Joining ' + e.title + '\u2026')}
          onOpenCalendar={(id) => setCalendarModalEventId(id)}
          onCancelRequest={requestCancelRegistration}
          onOpenRecording={openRecording}
        />
      </AppShell>
    );
  } else if (screen === 'past-events') {
    bodyEl = (
      <AppShell navRefs={navRefs} sidebarRef={sidebarRef} onOpenHelp={openHelp} activeKey="events" onNavigate={handleSidebarNav} {...shellProps}>
        <PastEvents
          watchedIds={watchedRecordingIds}
          filter={pastEventsFilter} setFilter={setPastEventsFilter}
          onBack={() => navigate('events')}
          onOpenRecording={openRecording}
        />
      </AppShell>
    );
  } else if (screen === 'community') {
    bodyEl = (
      <AppShell navRefs={navRefs} sidebarRef={sidebarRef} onOpenHelp={openHelp} activeKey="community" onNavigate={handleSidebarNav} {...shellProps}>
        <div className="tcx"><Community key={communityOpen || 'all'} open={communityOpen} user={user} toast={showToast} /></div>
      </AppShell>
    );
  } else if (screen === 'contractors') {
    bodyEl = (
      <AppShell navRefs={navRefs} sidebarRef={sidebarRef} onOpenHelp={openHelp} activeKey="contractors" onNavigate={handleSidebarNav} {...shellProps}>
        <div className="tcx"><Contractors key={contractorQ + ':' + (contractorProfId || '')} initQ={contractorQ} go={goApp} initProf={contractorProfId}
          fromEvent={contractorProfId && currentEventId ? { label: 'Back to event', onBack: () => { setContractorProfId(null); navigate('event-detail'); } } : null} /></div>
      </AppShell>
    );
  } else if (screen === 'messaging') {
    bodyEl = (
      <AppShell navRefs={navRefs} sidebarRef={sidebarRef} onOpenHelp={openHelp} activeKey="messaging" onNavigate={handleSidebarNav} {...shellProps}>
        <div className="tcx"><Messaging toast={showToast} /></div>
      </AppShell>
    );
  } else if (screen === 'vault') {
    bodyEl = (
      <AppShell navRefs={navRefs} sidebarRef={sidebarRef} onOpenHelp={openHelp} activeKey="vault" onNavigate={handleSidebarNav} {...shellProps}>
        <div className="tcx"><Vault toast={showToast} go={goApp} /></div>
      </AppShell>
    );
  } else if (screen === 'pipeline') {
    bodyEl = (
      <AppShell navRefs={navRefs} sidebarRef={sidebarRef} onOpenHelp={openHelp} activeKey="pipeline" onNavigate={handleSidebarNav} {...shellProps}>
        <div className="tcx"><Pipeline toast={showToast} go={goApp} /></div>
      </AppShell>
    );
  } else if (screen === 'settings') {
    bodyEl = (
      <AppShell navRefs={navRefs} sidebarRef={sidebarRef} onOpenHelp={openHelp} activeKey="settings" onNavigate={handleSidebarNav} {...shellProps}>
        <div className="tcx"><SettingsPage toast={showToast} user={user} /></div>
      </AppShell>
    );
  } else if (screen === 'help') {
    bodyEl = (
      <AppShell navRefs={navRefs} sidebarRef={sidebarRef} onOpenHelp={openHelp} activeKey="help" onNavigate={handleSidebarNav} {...shellProps}>
        <div className="tcx"><HelpPage onGo={(k) => (k === 'profile' ? navigate('profile') : handleSidebarNav(k))} onTour={reopenTour} toast={showToast} /></div>
      </AppShell>
    );
  } else if (screen === 'profile') {
    bodyEl = (
      <AppShell navRefs={navRefs} sidebarRef={sidebarRef} onOpenHelp={openHelp} activeKey="" onNavigate={handleSidebarNav} {...shellProps}>
        <div className="tcx"><Profile user={user} profile={profile} onSave={saveProfile} onClose={closeProfile} /></div>
      </AppShell>
    );
  } else if (screen === 'recording-player' && currentRecordingId) {
    const recording = findRecording(currentRecordingId);
    bodyEl = (
      <AppShell navRefs={navRefs} sidebarRef={sidebarRef} onOpenHelp={openHelp} activeKey="events" onNavigate={handleSidebarNav} {...shellProps}>
        <RecordingPlayer
          recording={recording}
          watched={!!watchedRecordingIds[recording.id]}
          liked={!!likedRecordingIds[recording.id]}
          saved={!!savedRecordingIds[recording.id]}
          onBack={() => navigate('past-events')}
          onLike={toggleLikeRecording}
          onSave={toggleSaveRecording}
          onShare={() => setShareModalEventId('recording:' + recording.id)}
          onDownloadResource={handleDownloadResource}
          onOpenUpNext={openRecording}
          onFirstPlay={() => markRecordingWatched(recording.id)}
        />
      </AppShell>
    );
  }

  return (
    <div className="tca">
      <style>{STYLES}</style>
      {bodyEl}
      {registerModalEventId && (
        <RegisterModal
          event={findEvent(registerModalEventId)}
          onOpenCalendarOption={(kind) => handleCalendarOption(kind, findEvent(registerModalEventId))}
          onViewMyEvents={() => { setRegisterModalEventId(null); navigate('my-events'); }}
          onClose={() => setRegisterModalEventId(null)}
        />
      )}
      {calendarModalEventId && (
        <CalendarModal
          event={findEvent(calendarModalEventId)}
          onSelect={(kind) => { handleCalendarOption(kind, findEvent(calendarModalEventId)); setCalendarModalEventId(null); }}
          onClose={() => setCalendarModalEventId(null)}
        />
      )}
      {cancelModalEventId && (
        <CancelModal
          event={findEvent(cancelModalEventId)}
          onKeep={() => setCancelModalEventId(null)}
          onCancel={confirmCancelRegistration}
          onClose={() => setCancelModalEventId(null)}
        />
      )}
      {shareModalEventId && (() => {
        const isRecording = shareModalEventId.indexOf('recording:') === 0;
        const target = isRecording ? findRecording(shareModalEventId.slice(10)) : findEvent(shareModalEventId);
        return target ? (
          <ShareModal
            event={target}
            onShare={(kind) => handleShareOption(kind, target)}
            onClose={() => setShareModalEventId(null)}
          />
        ) : null;
      })()}
      {tourOpen && (
        <TourOverlay
          step={tourStep}
          navRefs={navRefs}
          onNext={tourNext}
          onBack={tourBack}
          onSkip={tourSkip}
          onClose={tourSkip}
        />
      )}
      <Toast message={toastMsg} />
    </div>
  );
}

/* ============================================================
   Demo video asset
   ------------------------------------------------------------
   The uploaded video (VIDEO_URL_OVERRIDE.mp4) is embedded below as DEMO_VIDEO_B64 and is what every player uses.
   To serve it from a file instead, set VIDEO_URL_OVERRIDE to its path (e.g. '/VIDEO_URL_OVERRIDE.mp4') and delete DEMO_VIDEO_B64.
   ============================================================ */
const VIDEO_URL_OVERRIDE = '';
const DEMO_VIDEO_B64 = '';